      { text: "¿Cómo se manifiesta la 'Metis' de Odiseo durante la tormenta?", options: ["Peleando con las olas", "En su capacidad de razonar y tomar decisiones rápidas bajo presión extrema", "Llorando", "Pidiendo ayuda a gritos"], correctAnswer: 1 },
      { text: "¿Qué dice Calipso sobre la belleza de Penélope comparada con la suya?", options: ["Que Penélope es más bella", "Que una mortal no puede competir en belleza con una diosa inmortal", "Que son iguales", "Que Penélope ya es vieja"], correctAnswer: 1 },
      { text: "¿Cuál es la respuesta de Odiseo a la oferta de inmortalidad de Calipso?", options: ["La acepta feliz", "La rechaza, prefiriendo su humanidad y su destino mortal en su patria", "Dice que lo pensará", "Se ríe de ella"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la descripción de la cueva de Calipso?", options: ["Es un lugar feo", "Representa un 'locus amoenus' o paraíso natural que tienta al héroe al olvido", "Es una prisión oscura", "Es un templo de Zeus"], correctAnswer: 1 },
      { text: "¿Cómo se describe el vuelo de Hermes hacia Ogigia?", options: ["Como un pájaro que pesca", "Como una gaviota que roza las olas del mar", "Como un rayo", "Como un barco"], correctAnswer: 1 },
      { text: "¿Qué hace Odiseo con el velo de Ino tras tocar tierra?", options: ["Lo usa de manta", "Cumple su promesa de arrojarlo al mar sin mirar atrás", "Se lo da a los Feacios", "Lo pierde en la arena"], correctAnswer: 1 },
      { text: "¿Qué vientos envía Poseidón para crear la tormenta?", options: ["Solo uno", "Euro, Noto, Céfiro y Bóreas (los cuatro vientos principales)", "Vientos suaves", "Un huracán sin nombre"], correctAnswer: 1 },
      { text: "¿Qué teme Odiseo al ver la costa de Esqueria por primera vez?", options: ["Que no haya comida", "Que la falta de puertos y las rocas lo maten al intentar desembarcar", "Que los Feacios sean gigantes", "Que Calipso lo haya seguido"], correctAnswer: 1 },
      { text: "¿Cómo se siente Odiseo respecto a su muerte en el mar?", options: ["Desea morir", "Lamenta no haber muerto en Troya con honor en lugar de morir de forma oscura", "No tiene miedo", "Cree que Zeus lo salvará"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene el 'olivo silvestre' y el 'olivo injertado'?", options: ["Es un detalle botánico", "Simboliza la unión de la naturaleza salvaje y la civilización que Odiseo representa", "Es leña para el fuego", "Es una señal de Poseidón"], correctAnswer: 1 },
      { text: "¿Quién es el 'hijo de Cronos' mencionado a menudo?", options: ["Poseidón", "Zeus", "Hades", "Odiseo"], correctAnswer: 1 },
      { text: "¿Qué hace Atenea con los pensamientos de Odiseo cuando está a punto de estrellarse?", options: ["Se los quita", "Le infunde una idea para que se agarre a la roca con ambas manos", "Lo hace dormir", "Lo vuelve loco"], correctAnswer: 1 },
      { text: "¿Cómo se describe la piel de Odiseo tras la lucha con las rocas?", options: ["Limpia", "Desollada y pegada a las piedras como las ventosas de un pulpo", "Bronceada", "Cubierta de oro"], correctAnswer: 1 },
      { text: "¿Qué representa el 'fuego' en la comparación final del canto?", options: ["Una destrucción", "La chispa de vida que Odiseo conserva ocultándose bajo las hojas", "La ira de Poseidón", "Un regalo de Hermes"], correctAnswer: 1 },
      { text: "¿Qué dice Calipso sobre el destino de Odiseo si se va?", options: ["Que será feliz", "Que sufrirá muchas penas antes de llegar a su patria", "Que morirá mañana", "Que se perderá para siempre"], correctAnswer: 1 },
      { text: "¿Cómo es el trato de Calipso hacia Hermes?", options: ["Hostil", "Hospitalario, ofreciéndole ambrosía y néctar", "Indiferente", "De miedo"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene el 'tridente' de Poseidón?", options: ["Es un adorno", "Es el instrumento con el que agita el mar y la tierra", "Es un regalo de Zeus", "Es para pescar"], correctAnswer: 1 },
      { text: "¿Cómo se describe el estado físico de Odiseo al salir del río?", options: ["Fuerte", "Con las rodillas dobladas, el corazón desmayado y echando agua por la boca", "Listo para correr", "Dormido"], correctAnswer: 1 },
      { text: "¿Cuál es el sentimiento final de Odiseo al dormirse bajo las hojas?", options: ["Terror", "Un alivio profundo tras haber escapado de la muerte en el mar", "Tristeza por Calipso", "Hambre"], correctAnswer: 1 }
