      { text: "¿Qué importancia tiene el 'baño caliente' que toma Odiseo?", options: ["Solo higiene", "Es un lujo que simboliza la paz y el cuidado de la civilización feacia", "Es una trampa", "Es un castigo"], correctAnswer: 1 },
      { text: "¿Cómo se describe el nudo que Odiseo hace en su cofre?", options: ["Como un nudo marinero", "Como un secreto técnico que muestra su ingenio y precaución", "Como algo que Nausícaa hizo", "Como un regalo de Zeus"], correctAnswer: 1 },
      { text: "¿Qué dice Alcinoo sobre la relación entre el dolor y la canción?", options: ["Que el dolor es malo", "Que los dioses traman desgracias para que los hombres tengan qué cantar", "Que la música cura todo", "Que no hay relación"], correctAnswer: 1 },
      { text: "¿Qué representa el 'Caballo de Troya' en la carrera de Odiseo?", options: ["Su mayor derrota", "Su mayor triunfo de la inteligencia (Metis) sobre la fuerza", "Un regalo de Poseidón", "Una mentira de Demódoco"], correctAnswer: 1 },
      { text: "¿Cómo reacciona la asamblea ante el discurso de Odiseo tras el disco?", options: ["Con risas", "Con un silencio de asombro y respeto", "Con abucheos", "Con miedo"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la mención de los 'hijos de los dioses'?", options: ["Es un insulto", "Refuerza el estatus semidivino de los héroes y los nobles feacios", "Es un error", "No se mencionan"], correctAnswer: 1 },
      { text: "¿Cómo se describe la red de Hefesto?", options: ["Como una red de pesca", "Fina como telas de araña e invisible incluso para los dioses", "Como una cadena de hierro", "Como una trampa de madera"], correctAnswer: 1 },
      { text: "¿Qué dice Odiseo sobre su habilidad con la lanza?", options: ["Que es mala", "Que puede lanzarla más lejos de lo que otros disparan una flecha", "Que prefiere la espada", "Que no sabe usarla"], correctAnswer: 1 },
      { text: "¿Qué representa el 'arca' de regalos para el futuro de Odiseo?", options: ["Un peso muerto", "La recuperación de su riqueza y su estatus como rey", "Una trampa de Alcinoo", "Un regalo para Penélope"], correctAnswer: 1 },
      { text: "¿Cómo se siente Odiseo respecto a los Feacios al final de los juegos?", options: ["Los desprecia", "Admira su excelencia en la danza y la navegación", "Les tiene envidia", "Quiere conquistarlos"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la 'ceguera' de Demódoco?", options: ["Es un castigo", "Se compensa con el don divino de la visión interior y la poesía", "Es una mentira", "Le impide cantar bien"], correctAnswer: 1 },
      { text: "¿Qué dice Alcinoo sobre el llanto de Odiseo?", options: ["Que es de mujer", "Que debe tener una razón profunda ligada a sus amigos muertos en Troya", "Que es por hambre", "Que es por Nausícaa"], correctAnswer: 1 },
      { text: "¿Cómo se describe la hospitalidad de Alcinoo en este canto?", options: ["Como algo forzado", "Como una generosidad que busca honrar al huésped por encima de todo", "Como una forma de presumir", "Como una carga"], correctAnswer: 1 },
      { text: "¿Qué sentimiento evoca el final del Canto VIII?", options: ["Tristeza", "Una tensión máxima ante la inminente revelación de la identidad del héroe", "Aburrimiento", "Paz absoluta"], correctAnswer: 1 }
