    adulto: [
      { text: "¿Analice la 'Nekyia' como una experiencia de descentramiento del ego heroico.", options: ["Es un triunfo del ego", "El héroe se reduce a un observador frente a la inmensidad del pasado y la muerte", "Es una mentira de Odiseo", "Es un sueño"], correctAnswer: 1 },
      { text: "¿Qué representa la sangre como 'moneda de cambio' ontológica?", options: ["Un desperdicio", "El vínculo material que permite a la conciencia incorpórea recuperar la memoria y el habla", "Un regalo para los dioses", "Una trampa de Circe"], correctAnswer: 1 },
      { text: "¿Cómo funciona el encuentro con Aquiles como una crítica a la 'Aristeia' épica?", options: ["La refuerza", "Cuestiona el valor de la gloria póstuma frente a la existencia más humilde pero viva", "Muestra que Aquiles es un cobarde", "Es un error de Homero"], correctAnswer: 1 },
      { text: "¿Analice el silencio de Ayante desde la perspectiva del honor (Timé).", options: ["Es falta de educación", "El honor herido es tan absoluto que trasciende la muerte y anula la comunicación", "Es un perdón silencioso", "Es porque no tiene lengua"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la profecía de Tiresias sobre el 'remo' y la 'pala'?", options: ["Es un detalle técnico", "Representa la necesidad de llevar la cultura del mar a lo desconocido para cerrar el ciclo de Poseidón", "Es un error de traducción", "Es una broma"], correctAnswer: 1 },
      { text: "¿Cómo se manifiesta la dialéctica entre lo Masculino y lo Femenino en el Hades?", options: ["No hay distinción", "A través de la larga lista de heroínas que fundamentan la genealogía y el orden social", "Las mujeres son sombras menores", "Solo importan los guerreros"], correctAnswer: 1 },
      { text: "¿Analice la figura de Agamenón como el espejo trágico del 'Nostos'.", options: ["Es un éxito", "Representa el fracaso absoluto del regreso y la advertencia sobre la fragilidad del hogar", "Es un mentiroso", "Es un dios"], correctAnswer: 1 },
      { text: "¿Qué representan los castigos de Tántalo y Sísifo en la filosofía existencial?", options: ["Mala suerte", "La condena al deseo perpetuo y al trabajo absurdo como esencia del sufrimiento humano", "Justicia divina", "Brumas del Hades"], correctAnswer: 1 },
      { text: "¿Cómo funciona la sombra de Anticlea como motor emocional del regreso?", options: ["No tiene efecto", "Convierte el 'Nostos' de una meta política en una necesidad afectiva y de duelo", "Hace que Odiseo quiera morir", "Le da miedo"], correctAnswer: 1 },
      { text: "¿Analice la estructura de la 'Nekyia' como un catálogo de la memoria cultural griega.", options: ["Es un desorden", "Organiza el pasado mítico y heroico bajo la mirada del presente de Odiseo", "Es una invención de Circe", "Es para asustar a los Feacios"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la figura de Minos en la escatología homérica?", options: ["Es un detalle", "Sugiere que el orden y la ley son principios universales que rigen incluso el caos de la muerte", "Es un tirano", "Es un amigo de Odiseo"], correctAnswer: 1 },
      { text: "¿Cómo se describe la 'psique' (alma) en este canto?", options: ["Como algo eterno", "Como una sombra vana, un simulacro del ser que carece de voluntad propia sin la sangre", "Como un dios", "Como un cuerpo sólido"], correctAnswer: 1 },
      { text: "¿Analice el encuentro con Heracles como una paradoja de la identidad.", options: ["Es muy simple", "Muestra la división entre la sombra sufriente y la esencia divina que habita con los dioses", "Es una mentira", "Heracles es un fantasma"], correctAnswer: 1 },
      { text: "¿Qué representa el terror final de Odiseo ante la Gorgona?", options: ["Cobardía", "El límite de lo que la mente humana puede soportar antes de la disolución total", "Un truco de Perséfone", "Una broma de los muertos"], correctAnswer: 1 },
      { text: "¿Cómo se manifiesta el tema de la 'Fidelidad' en las palabras de Anticlea?", options: ["Como una mentira", "Como la fuerza que sostiene a Penélope y, por extensión, la esperanza de Odiseo", "Como una carga", "No se menciona"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la mención de Neoptólemo para la ética del linaje?", options: ["Ninguna", "La gloria del hijo redime el sufrimiento del padre en el más allá", "Es una envidia", "Es un error"], correctAnswer: 1 },
      { text: "¿Analice la advertencia de Tiresias sobre las vacas de Helios como prueba moral.", options: ["Es una dieta", "Representa la capacidad de autocontrol frente a la necesidad física extrema", "Es una trampa de los dioses", "Es un detalle menor"], correctAnswer: 1 },
      { text: "¿Qué representa el 'Océano' como espacio de transición?", options: ["Un mar común", "La barrera infranqueable que separa la luz de la razón de la oscuridad del origen", "Un charco", "La casa de Poseidón"], correctAnswer: 1 },
      { text: "¿Cómo se describe la relación entre 'Conocimiento' y 'Sufrimiento' en el Hades?", options: ["No hay relación", "Saber el futuro (Tiresias) o el pasado (madre) aumenta la carga trágica del héroe", "El conocimiento da paz", "El sufrimiento es ignorancia"], correctAnswer: 1 },
      { text: "¿Analice el papel de Perséfone en la gestión de las sombras.", options: ["Es una reina pasiva", "Es la voluntad divina que permite o prohíbe el acceso a la conciencia de los muertos", "Es una enemiga", "No aparece"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene el rito de llamar tres veces a los muertos?", options: ["Es una superstición", "Es el acto de reconocimiento que fija la memoria del difunto en el mundo de los vivos", "Es para despertarlos", "Es una broma"], correctAnswer: 1 },
      { text: "¿Cómo se manifiesta la 'Justicia' en el Hades?", options: ["No existe", "A través de los castigos ejemplares para quienes desafiaron el orden cósmico", "Es aleatoria", "Es solo para los pobres"], correctAnswer: 1 },
      { text: "¿Qué representa la sombra de Orión en la eternidad del Hades?", options: ["Un cazador feliz", "La repetición infinita de las acciones terrenales despojadas de su fruto real", "Un dios", "Un enemigo"], correctAnswer: 1 },
      { text: "¿Analice el sentimiento de 'Nostalgia' (dolor por el regreso) en este canto.", options: ["Es debilidad", "Es el motor que impulsa a Odiseo a través del reino de la muerte", "Es una mentira", "Es por Circe"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene la mención de la 'pala de aventar' como símbolo de paz?", options: ["Es para el campo", "Marca el fin del conflicto con Poseidón y la integración final del héroe en la tierra", "Es un arma", "Es un regalo"], correctAnswer: 1 },
      { text: "¿Cómo se describe la 'belleza' de las heroínas muertas?", options: ["Como algo vivo", "Como un recuerdo melancólico de una grandeza que ya no tiene lugar en el mundo", "Como algo feo", "Como diosas"], correctAnswer: 1 },
      { text: "¿Qué representa el 'sacrificio' como puente entre mundos?", options: ["Un desperdicio", "El acto sagrado que permite la comunicación entre lo finito y lo infinito", "Una trampa", "Un regalo"], correctAnswer: 1 },
      { text: "¿Analice la 'soledad' de Odiseo rodeado de miles de sombras.", options: ["Es compañía", "Es la soledad del vivo ante la mudez y el vacío de la muerte", "Es alegría", "Es una mentira"], correctAnswer: 1 },
      { text: "¿Qué importancia tiene el encuentro con Ticio, Tántalo y Sísifo?", options: ["Son cuentos", "Establecen los límites morales del comportamiento humano frente a lo divino", "Son amigos de Odiseo", "Son jueces"], correctAnswer: 1 },
      { text: "¿Qué sentimiento evoca el final del Canto XI respecto a la condición humana?", options: ["Paz", "Una profunda inquietud ante la fragilidad de la vida y la persistencia del deseo", "Felicidad", "Indiferencia"], correctAnswer: 1 }
    ]
